lessons.solution_code:
def run_cases(fn, cases):
    for args, expected in cases:
        assert fn(*args) == expected
    return len(cases)

tests.unittest_code:
def test_run_cases(self):
    n = run_cases(lambda a, b: a + b, [((1, 2), 3), ((0, 0), 0)])
    self.assertEqual(n, 2)

